    /// <summary>Runs the exceptions/tag tests.</summary>
    [TestMethod]
    public void SpecTest_exceptions_tag()
        // Tags defined inside a (rec …) group are matched by their iso-recursive canonical descriptor, which
        // distinguishes a tag by its group structure and member position, so an import naming a tag whose type is a
        // different rec-group member than the exporter's is correctly rejected.
        => SpecTestRunner.Run("exceptions/tag");

