    /// <summary>Runs the type-rec tests.</summary>
    [TestMethod]
    public void SpecTest_type_rec()
        // Recursive/structural type groups: the iso-recursive canonical type map distinguishes members of a rec
        // group, so "type mismatch" assert_invalid cases are rejected. A function import whose declared type is a
        // distinct rec-group member is matched by the exported function's canonical ancestry at link time, and a
        // call_indirect over a canonically-distinct table function is trapped by the call_indirect canonical guard.
        => SpecTestRunner.Run("type-rec");


